شاول ۳ 100 ساعت توقف کرده. ریشه و هزینه چقدر بود؟ (مدیر تعمیرات — معدن سنگ‌آهن گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "equipment_downtime",
      "description": "توقف تجهیزات به تفکیک نوع و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours",
        "cost"
      ]
    },
    {
      "dataset": "equipment_condition",
      "description": "وضعیت فنی تجهیزات",
      "dimensions": [
        "equipment"
      ],
      "measures": [
        "age_years",
        "hours_run",
        "last_overhaul"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "availability",
      "description": "نرخ دسترسی تجهیز",
      "formula": "زمان کار / (زمان کار + زمان توقف)",
      "unit": "درصد",
      "dimensions": [
        "equipment"
      ]
    },
    {
      "metric": "mtbf",
      "description": "میانگین زمان بین خرابی‌ها",
      "formula": "کل زمان کار / تعداد خرابی‌ها",
      "unit": "ساعت",
      "dimensions": [
        "equipment"
      ]
    }
  ],
  "business_context": [
    "ناوگان تجهیزات معدنی شامل شاول، دامپر، سنگ‌شکن و آسیاب",
    "تعمیرات پیشگیرانه و اضطراری با بودجهٔ سالانه",
    "قطعات حیاتی با زمان تحویل طولانی (۳ تا ۶ ماه)"
  ]
}

